def b(n,c='',a=None):return '<!-- wp:'+n+(' '+json.dumps(a,separators=(',',':')) if a else '')+' -->'+c+'<!-- /wp:'+n+' -->'
def p(s,c=''):return b('paragraph','<p'+(' class="'+c+'"' if c else '')+'>'+s+'</p>',{'className':c} if c else None)
def h(s,n=2):return b('heading',f'<h{n} class="wp-block-heading">{s}</h{n}>',{'level':n})
