def image(name,alt,c=''):return b('image',f'<figure class="wp-block-image {c}"><img src="{{{{ASSET}}}}/{name}.webp" alt="{alt}"/></figure>',{'className':c})
def a(label,to='{{BOOKING}}',ghost=False):return b('buttons',b('button',f'<div class="wp-block-button'+(' is-style-outline' if ghost else '')+f'"><a class="wp-block-button__link wp-element-button" href="{to}">{label} <span aria-hidden="true">↗</span></a></div>',{'className':'is-style-outline'} if ghost else None))
def section(s,c=''):return g(g(s,'wrap'),'section '+c,'section')
